parameters.jsCode:
const items = $input.all();
return items.map(item => {
  const zapData = item.json.body || item.json;
  const zapName = zapData.name || zapData.zapName || 'Untitled Zap';
  const steps = zapData.steps || zapData.actions || [];
  const triggerApp = zapData.trigger?.app || steps[0]?.app || 'unknown';
  const triggerEvent = zapData.trigger?.event || steps[0]?.event || 'unknown';

  const nodeMapping = {
    'gmail': 'n8n-nodes-base.gmail',
    'google_sheets': 'n8n-nodes-base.googleSheets',
    'slack': 'n8n-nodes-base.slack',
    'trello': 'n8n-nodes-base.trello',
    'airtable': 'n8n-nodes-base.airtable',
    'mailchimp': 'n8n-nodes-base.mailchimp',
    'hubspot': 'n8n-nodes-base.hubspot',
    'asana': 'n8n-nodes-base.asana',
    'github': 'n8n-nodes-base.github',
    'jira': 'n8n-nodes-base.jira'
  };

  const n8nNodes = steps.map((step, idx) => ({
    app: step.app || 'unknown',
    n8nEquivalent: nodeMapping[step.app?.toLowerCase()] || 'n8n-nodes-base.httpRequest',
    action: step.action || step.event || 'unknown',
    migrationNotes: nodeMapping[step.app?.toLowerCase()] ? 'Direct equivalent available' : 'Use HTTP Request node or search n8n integrations'
  }));

  return {
    json: {
      originalZapName: zapName,
      triggerApp: triggerApp,
      triggerEvent: triggerEvent,
      totalSteps: steps.length,
      mappedNodes: JSON.stringify(n8nNodes),
      migrationStatus: 'mapped',
      timestamp: new Date().toISOString(),
      recommendations: n8nNodes.filter(n => n.n8nEquivalent === 'n8n-nodes-base.httpRequest').length > 0
        ? 'Some nodes require HTTP Request — check n8n integrations for native nodes'
        : 'All nodes have direct n8n equivalents'
    }
  };
});

